def reserver(reservations, identifiant, equipement, debut, fin):
    if not (debut >= 0 and debut < fin and fin <= 1440):
        return None
    for r in reservations:
        if r["id"] == identifiant:
            return None
        if r["active"] and r["equipement"] == equipement and debut < r["fin"] and r["debut"] < fin:
            return None
    copie = []
    for r in reservations:
        copie.append(r.copy())
    copie.append({"id":identifiant, "equipement":equipement, "debut":debut, "fin":fin, "active":True})
    return copie

def annuler(reservations, identifiant):
    trouve = False
    for r in reservations:
        if r["id"] == identifiant and r["active"]:
            trouve = True
    if not trouve:
        return None
    copie = []
    for r in reservations:
        fiche = r.copy()
        if fiche["id"] == identifiant:
            fiche["active"] = False
        copie.append(fiche)
    return copie

def traiter_reservations(reservations, operations):
    etat = []
    for r in reservations:
        etat.append(r.copy())
    refus = 0
    for op in operations:
        suivant = None
        if op["type"] == "reserver":
            suivant = reserver(etat, op["id"], op["equipement"], op["debut"], op["fin"])
        elif op["type"] == "annuler":
            suivant = annuler(etat, op["id"])
        if suivant == None:
            refus = refus + 1
        else:
            etat = suivant
    return {"reservations": etat, "refus": refus}
